CREATE TABLE IF NOT EXISTS LShufWork_AFill (Ord INTEGER, LeaderType TEXT, CardId TEXT);
DELETE FROM LShufWork_AFill;
CREATE TABLE IF NOT EXISTS LShufWork_AFillTried (Ord INTEGER PRIMARY KEY);
DELETE FROM LShufWork_AFillTried;
DELETE FROM LShufWork_AFill;
INSERT INTO LShufWork_AFill (Ord, LeaderType) SELECT x.Ord, x.LeaderType FROM LShufWork_ADealt x WHERE x.CardId IS NULL
  AND NOT EXISTS (SELECT 1 FROM LShufWork_AFillTried t WHERE t.Ord = x.Ord) ORDER BY x.Ord LIMIT 1;
UPDATE LShufWork_AFill SET CardId = (SELECT r.CardId FROM (SELECT a.CardId AS CardId, CASE WHEN EXISTS (SELECT 1 FROM LShufWork_ADealt d JOIN LShufWork_ACard b ON b.CardId = d.CardId
          WHERE d.LeaderType = LShufWork_AFill.LeaderType AND b.TraitType = a.TraitType) THEN 1 ELSE 0 END AS H,
      CASE WHEN a.FromLeader = LShufWork_AFill.LeaderType THEN 1 ELSE 0 END AS Own, a.Ord AS Ord FROM LShufWork_ACard a
      WHERE NOT EXISTS (SELECT 1 FROM LShufWork_ADealt d WHERE d.CardId = a.CardId)) r
    ORDER BY r.H, r.Own, r.Ord LIMIT 1);
INSERT OR IGNORE INTO LShufWork_AFillTried (Ord) SELECT Ord FROM LShufWork_AFill;
UPDATE LShufWork_ADealt SET CardId = (SELECT CardId FROM LShufWork_AFill) WHERE Ord = (SELECT Ord FROM LShufWork_AFill) AND (SELECT CardId FROM LShufWork_AFill) IS NOT NULL;
DELETE FROM LShufWork_AFill;
